function langSwitch(){return `<div class="lang"><button class="${S.lang==='az'?'active':''}" data-lang="az">AZ</button><button class="${S.lang==='en'?'active':''}" data-lang="en">EN</button></div>`}
function logo(){return `<div class="logo" data-go="landing"><img class="logo-image" src="assets/talantup-logo.jpeg" alt="TalantUp"></div>`}
function render(){const app=$('#app');app.innerHTML=S.route==='landing'?landing():S.route==='auth'?auth():dashboard();bind();document.title=`${S.route==='dashboard'?pageTitle():'TalantUp'} — TalantUp`;}
function landing(){return `<div class="landing"><nav class="public-nav">${logo()}<div class="nav-actions">${langSwitch()}<button class="btn btn-secondary" data-auth="youth">${t('login')}</button></div></nav><section class="hero"><span class="eyebrow">${I('spark')} Hackathon concept • Frontend demo</span><h1>${t('headline')}</h1><p>${t('hero')}</p><div class="hero-actions"><button class="btn btn-primary" data-demo="youth">${I('spark')} ${t('demo')}</button><a class="btn btn-secondary" href="#roles">${S.lang==='az'?'Rollar ilə tanış ol':'Explore roles'}</a></div></section><section class="roles" id="roles">${Object.entries(roles).map(([k,r])=>`<article class="role-card"><span class="role-icon">${I(r.icon)}</span><h3>${r.name()}</h3><p>${r.desc()}</p><div class="actions"><button class="btn btn-primary" data-auth="${k}">${t('login')}</button><button class="btn btn-secondary" data-demo="${k}">${I('spark')} ${t('demo')}</button></div></article>`).join('')}</section><section class="how"><div class="section-head"><h2>${t('how')}</h2><p>${t('howSub')}</p></div><div class="steps">${[t('step1'),t('step2'),t('step3')].map((x,i)=>`<div class="step"><span class="step-num">0${i+1}</span><h3>${x}</h3><p>${S.lang==='az'?'Profilini tamamla və növbəti addımı aydın şəkildə gör.':'Complete your profile and see the next step clearly.'}</p></div>`).join('')}</div></section><footer class="footer"><span>© 2026 TalantUp • Concept prototype</span><span>${S.lang==='az'?'Real işə qəbul qərarları və AI xidməti istifadə edilmir.':'No real hiring decisions or AI service are used.'}</span></footer></div>`}
function auth(){const r=roles[S.role], reg=S.authTab==='register';return `<div class="auth"><section class="auth-side">${logo()}<div class="auth-copy"><span class="demo-label">${I(r.icon)} ${r.name()}</span><h1>${S.lang==='az'?'İmkanlara aparan profilini qur.':'Build a profile that opens opportunities.'}</h1><p>${r.desc()}</p><div class="auth-steps">${[t('step1'),t('step2'),t('step3')].map((x,i)=>`<div class="auth-step"><b>${i+1}</b>${x}</div>`).join('')}</div><div class="role-switch">${Object.keys(roles).map(k=>`<button class="${S.role===k?'active':''}" data-auth="${k}">${roles[k].name()}</button>`).join('')}</div></div></section><section class="auth-panel"><div class="auth-top">${langSwitch()}</div><div class="auth-box"><h2>${reg?(S.lang==='az'?'Hesabını yarat':'Create your account'):(S.lang==='az'?'Yenidən xoş gəldin':'Welcome back')}</h2><p>${S.lang==='az'?'Bu form təqdimat üçündür. Məlumatlar serverə göndərilmir.':'This form is for demonstration. Data is not sent to a server.'}</p><div class="tabs"><button class="tab ${!reg?'active':''}" data-tab="login">${S.lang==='az'?'Giriş':'Login'}</button><button class="tab ${reg?'active':''}" data-tab="register">${S.lang==='az'?'Qeydiyyat':'Register'}</button></div><form id="auth-form" class="form-grid">${authFields(reg)}<div class="field full auth-buttons"><button class="btn btn-primary" type="submit">${reg?(S.lang==='az'?'Davam et':'Continue'):(S.lang==='az'?'Daxil ol':'Sign in')}</button></div></form><div class="divider">${S.lang==='az'?'və ya':'or'}</div><button class="btn btn-secondary" style="width:100%" data-demo="${S.role}">${I('spark')} ${t('enterDemo')}</button><button class="btn btn-ghost" style="width:100%;margin-top:8px" data-go="landing">← ${S.lang==='az'?'İctimai ana səhifəyə qayıt':'Back to public home'}</button></div></section></div>`}
function f(label,type='text',name='',full=''){return `<div class="field ${full}"><label>${label}</label><input type="${type}" name="${name||label}" required /></div>`}
function authFields(reg){if(!reg)return f(S.lang==='az'?'E-poçt':'Email','email','email')+f(S.lang==='az'?'Şifrə':'Password','password','password');if(S.role==='youth')return f(S.lang==='az'?'Ad və soyad':'Full name','text','name')+f('Email','email','email')+f(S.lang==='az'?'Şifrə':'Password','password','password')+f(t('city'),'text','city')+f(S.lang==='az'?'Təhsil / fəaliyyət sahəsi':'Education / activity area','text','education')+`<div class="field"><label>${S.lang==='az'?'Maraq':'Interest'}</label><select required><option value="">${S.lang==='az'?'Seçin':'Select'}</option><option>${t('jobs')}</option><option>${t('volunteer')}</option><option>${S.lang==='az'?'Hər ikisi':'Both'}</option></select></div><label class="upload"><input type="file" id="cv-file" accept=".pdf,.doc,.docx"><strong>${I('file')} ${S.lang==='az'?'CV faylını seç':'Choose CV file'}</strong><div class="muted small" id="file-name">PDF və ya DOCX • yalnız vizual demo</div><div class="upload-progress"><span id="upload-bar" style="width:0"></span></div></label>`;if(S.role==='org')return f(S.lang==='az'?'Təşkilat adı':'Organization name','text','org')+f(S.lang==='az'?'Təşkilat növü':'Organization type','text','type')+f('Email','email','email')+f(t('city'),'text','city')+f(S.lang==='az'?'Əlaqələndirici şəxs':'Contact person','text','contact')+f(S.lang==='az'?'Şifrə':'Password','password','password');return f(S.lang==='az'?'Şirkət adı':'Company name','text','company')+f(S.lang==='az'?'Şirkət e-poçtu':'Company email','email','email')+f(S.lang==='az'?'HR əməkdaşının adı':'HR name','text','hr')+f(S.lang==='az'?'Sektor':'Sector','text','sector')+f(t('city'),'text','city')+f(S.lang==='az'?'Şifrə':'Password','password','password')}
const nav={youth:[['home','home','home'],['smartcv','spark','smartcv'],['jobs','brief','jobs'],['volunteer','heart','volunteer'],['applications','file','applications'],['activities','check','activities'],['badges','award','badges']],org:[['home','home','home'],['events','calendar','events'],['create-event','plus','createEvent'],['org-apps','users','applications'],['attendance','check','attendance'],['map','map','map'],['reports','chart','reports']],hr:[['home','home','home'],['matching','spark','matching'],['vacancies','brief','vacancies'],['create-vacancy','plus','createVacancy'],['candidates','users','candidates'],['saved','save','saved']]};
function dashboard(){const profile=S.role==='youth'?'Aysel Məmmədova':S.role==='org'?'EcoHub':'Nova People';return `<div class="shell">${S.menu?'<div class="mobile-overlay" data-close-menu></div>':''}<aside class="sidebar ${S.menu?'open':''}">${logo()}<nav class="side-nav">${nav[S.role].map(([p,ic,k],i)=>`<button class="nav-item ${S.page===p?'active':''} ${i===1?'ai-item':''}" data-page="${p}">${I(ic)}${t(k)}</button>`).join('')}</nav><div class="side-bottom"><button class="nav-item" data-page="profile">${I('user')}${S.role==='org'?(S.lang==='az'?'Təşkilat profili':'Organization Profile'):S.role==='hr'?(S.lang==='az'?'Şirkət profili':'Company Profile'):t('profile')}</button>${langSwitch()}<button class="nav-item" data-go="landing">${I('logout')}${t('logout')}</button></div></aside><main class="main"><header class="topbar"><button class="close menu-btn" data-menu>${I('menu')}</button><span class="top-title">${pageTitle()}</span><div class="top-actions">${langSwitch()}<div class="profile-mini"><span class="avatar">${profile.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><b>${profile}</b><small>Demo profile</small></div></div></div></header><div class="content">${page()}</div></main></div>`}
function pageTitle(){const item=nav[S.role].find(x=>x[0]===S.page);return item?t(item[2]):t('profile')}
function page(){if(S.page==='home')return home();if(S.page==='jobs')return opportunities('job');if(S.page==='volunteer')return opportunities('vol');if(S.page==='smartcv')return smartcv();if(S.page==='candidates'||S.page==='saved')return candidatePage();if(S.page==='matching')return matching();if(S.page==='events')return eventsPage();if(S.page==='map')return mapPage();if(S.page==='create-event'||S.page==='create-vacancy')return createPage();if(S.page==='attendance')return attendance();if(S.page==='profile')return profile();return genericPage()}
function home(){if(S.role==='youth')return `<div class="page-head"><div><span class="demo-label">Demo profile</span><h1>${S.lang==='az'?'Salam, Aysel 👋':'Hello, Aysel 👋'}</h1><p>${S.lang==='az'?'Bu gün profilini daha güclü etmək üçün bir addım at.':'Take one step today to strengthen your profile.'}</p></div><button class="btn btn-primary" data-page="smartcv">${I('spark')} ${t('smartcv')}</button></div><div class="grid grid-4">${stat('XP balansı','1,240','orange','68%')}${stat(S.lang==='az'?'Təsdiqlənmiş fəaliyyət':'Verified activities','5','green','')}${stat(S.lang==='az'?'Qazanılmış nişan':'Earned badges','3','','')}${stat(S.lang==='az'?'Profil tamamlanması':'Profile completion','82%','','82%')}</div><div class="grid grid-2" style="margin-top:18px"><section class="card welcome"><span class="demo-label">${I('spark')} Demo profile</span><h2>${S.lang==='az'?'Təcrübən görünməyə hazırdır.':'Your experience is ready to be seen.'}</h2><p>${S.lang==='az'?'Könüllülük fəaliyyətlərini peşəkar CV dilinə çevir və uyğun imkanlara müraciət et.':'Turn volunteering activities into professional CV language and apply to relevant opportunities.'}</p><button class="btn btn-secondary" data-page="smartcv">${t('smartcv')} →</button></section><section class="card"><h3>${S.lang==='az'?'Növbəti tövsiyə':'Next recommendation'}</h3>${opMini(jobs[0])}<button class="btn btn-primary btn-sm" data-page="jobs">${t('jobs')} →</button></section></div><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3>${S.lang==='az'?'Son fəaliyyətlər':'Recent activities'}</h3><div class="list">${['Yaşıl Şəhər Günü','Karyera seminarı','Kitab kampaniyası'].map((x,i)=>`<div class="list-item"><span class="stat-icon">${I(i===0?'heart':'check')}</span><div class="grow"><b>${x}</b><div class="small muted">${i? 'Future Bridge':'EcoHub'} • ${S.lang==='az'?'Təsdiqlənib':'Verified'}</div></div><span class="badge badge-green">✓</span></div>`).join('')}</div></section><section class="card"><h3>${S.lang==='az'?'Profil tamamlanması':'Profile completion'}</h3><p class="muted small">${S.lang==='az'?'Bir dil və iki bacarıq əlavə etməklə profilini tamamla.':'Complete your profile by adding a language and two skills.'}</p><div class="progress"><span style="width:82%"></span></div><div class="list-item"><div class="grow"><b>82% complete</b><div class="muted small">${S.lang==='az'?'Növbəti: dillər':'Next: languages'}</div></div><button class="btn btn-secondary btn-sm" data-page="profile">${t('profile')}</button></div></section></div>`;
if(S.role==='org')return roleHome('org');return roleHome('hr')}
function stat(label,value,color,prog){const l=label.toLowerCase();const icon=color==='orange'?'award':l.includes('fəaliyyət')||l.includes('activit')?'check':l.includes('nişan')||l.includes('badge')?'award':l.includes('profil')?'user':l.includes('tədbir')||l.includes('event')?'calendar':l.includes('müraciət')||l.includes('namizəd')||l.includes('candidate')?'users':l.includes('vakan')?'brief':'chart';return `<div class="card stat-card"><div class="stat-top"><span class="muted small">${label}</span><span class="stat-icon">${I(icon)}</span></div><div class="stat-value">${value}</div>${prog?`<div class="progress ${color}"><span style="width:${prog}"></span></div>`:`<span class="small muted">Demo profile data</span>`}</div>`}
function opMini(o){return `<div class="list-item"><span class="company-logo">${o.company.slice(0,2).toUpperCase()}</span><div class="grow"><b>${o.title}</b><div class="small muted">${o.company} • ${o.city}</div></div></div>`}
function roleHome(role){const org=role==='org';return `<div class="page-head"><div><span class="demo-label">Demo workspace</span><h1>${org?(S.lang==='az'?'Sabahın xeyir, EcoHub':'Good morning, EcoHub'):(S.lang==='az'?'Salam, Nova People':'Hello, Nova People')}</h1><p>${org?(S.lang==='az'?'Tədbirlər və iştirakçılar üçün təqdimat görünüşü.':'A demo view for events and participants.'):(S.lang==='az'?'İstedad kəşfi üçün aydın, fəaliyyət əsaslı baxış.':'A clear, activity-based view for talent discovery.')}</p></div><button class="btn btn-primary" data-page="${org?'create-event':'matching'}">${I(org?'plus':'spark')} ${t(org?'createEvent':'matching')}</button></div><div class="grid grid-3">${stat(org?'Aktiv tədbirlər':'Aktiv vakansiyalar','3','','')}${stat(org?'Yeni müraciətlər':'Saxlanmış namizədlər','8','','')}${stat(org?'İştirak göstəricisi':'Baxılan profillər','76%','green','76%')}</div><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3>${org?'Upcoming event':'Recommended candidate'}</h3>${org?opMini({title:'Yaşıl Şəhər Günü',company:'15 noyabr • 10:00',city:'Dənizkənarı park'}):candidateCard(candidates[0],true)}</section><section class="card ai-banner"><div><span class="demo-label">${I('spark')} AI Demo</span><h3>${org?'Participant preview':'Example compatibility'}</h3><p class="muted small">${org?'Müraciətləri və iştirak statuslarını bir ekranda izləyin.':'See why sample profiles may align with a selected vacancy.'}</p></div><button class="btn btn-primary btn-sm" data-page="${org?'org-apps':'matching'}">${t('view')}</button></section></div>`}
function opportunities(type){const data=type==='job'?jobs:vols;const q=(S.filters.q||'').toLowerCase(),city=S.filters.city||'',format=S.filters.format||'';const filtered=data.filter(x=>(!q||(x.title+x.company+x.skills.join(' ')).toLowerCase().includes(q))&&(!city||x.city===city)&&(!format||x.format===format));return `<div class="page-head"><div><h1>${t(type==='job'?'jobs':'volunteer')}</h1><p>${S.lang==='az'?'Demo məlumatlarında axtar və filtrləri sına.':'Search demo data and try the filters.'}</p></div><span class="demo-label">Demo opportunities</span></div><div class="filters"><input class="input" data-filter="q" value="${S.filters.q||''}" placeholder="${t('search')}..."><select class="select" data-filter="city"><option value="">${t('city')}: ${t('all')}</option>${['Bakı','Gəncə','Sumqayıt','Onlayn'].map(x=>`<option ${city===x?'selected':''}>${x}</option>`).join('')}</select><select class="select" data-filter="format"><option value="">${S.lang==='az'?'Format: Hamısı':'Format: All'}</option>${(type==='job'?['Hibrid','Uzaqdan','Ofis']:['Online','Offline']).map(x=>`<option ${format===x?'selected':''}>${x}</option>`).join('')}</select><select class="select" data-filter="extra"><option value="">${type==='job'?(S.lang==='az'?'Təcrübə səviyyəsi':'Experience level'):(S.lang==='az'?'Mövzu':'Topic')}</option><option>Başlanğıc</option><option>Events</option></select><button class="btn btn-secondary" data-reset>${I('filter')} ${t('reset')}</button></div>${chips()}<div class="opportunity-grid">${filtered.map(x=>opCard(x,type)).join('')}</div>${!filtered.length?empty():''}`}
function chips(){const active=Object.entries(S.filters).filter(([,v])=>v);return active.length?`<div class="filter-chips">${active.map(([k,v])=>`<span class="chip">${v}<button data-remove-filter="${k}">×</button></span>`).join('')}<button class="btn btn-ghost btn-sm" data-reset>${t('reset')}</button></div>`:''}
function opCard(o,type){const applied=S.applied.has(o.id);return `<article class="card op-card" data-open-op="${o.id}" data-type="${type}"><div class="company"><span class="company-logo">${o.company.slice(0,2).toUpperCase()}</span><div><h3>${o.title}</h3><div class="small muted">${o.company}</div></div></div><div class="meta"><span>${I('map')} ${o.city}</span><span>${I('calendar')} ${o.date||o.format}</span><span>${o.role||o.type}</span></div><div class="skills">${o.skills.map(x=>`<span>${x}</span>`).join('')}</div><p>${o.desc||`${o.role} rolunda tədbirin uğurlu keçməsinə dəstək ol.`}</p><div class="card-actions"><button class="btn btn-secondary btn-sm" data-details="${o.id}" data-type="${type}">${t('view')}</button><button class="btn ${applied?'btn-secondary':'btn-primary'} btn-sm" data-apply="${o.id}" ${applied?'disabled':''}>${applied?`✓ ${t('applied')}`:t('apply')}</button></div></article>`}
function empty(){return `<div class="empty" style="grid-column:1/-1"><span class="role-icon">${I('search')}</span><h3>${S.lang==='az'?'Nəticə tapılmadı':'No results found'}</h3><p class="muted">${S.lang==='az'?'Filtrlərdən birini sil və yenidən yoxla.':'Remove a filter and try again.'}</p><button class="btn btn-secondary" data-reset>${t('reset')}</button></div>`}
function smartcv(){if(S.cvLoading)return `<div class="loading"><div class="spinner"></div><h2>${S.lang==='az'?'Demo CV təhlil edilir...':'Analyzing demo CV...'}</h2><p class="muted">AI Demo • ${S.lang==='az'?'Bacarıqlar və fəaliyyətlər strukturlaşdırılır.':'Structuring skills and activities.'}</p></div>`;return `<div class="page-head"><div><span class="demo-label">${I('spark')} AI Demo • Concept Preview</span><h1>${t('smartcv')}</h1><p>${S.lang==='az'?'Fəaliyyətlərini peşəkar CV dilində müqayisə et.':'Compare your activities in professional CV language.'}</p></div><button class="btn btn-secondary" data-download>${I('download')} ${S.lang==='az'?'Demo endirmə':'Demo download'}</button></div><div class="cv-layout"><aside class="card cv-tools"><button class="btn ${S.cvMode==='original'?'btn-primary':'btn-secondary'}" data-cv="original">${S.lang==='az'?'Orijinal versiya':'Original version'}</button><button class="btn ${S.cvMode==='improved'?'btn-primary':'btn-secondary'}" data-cv="improved">${S.lang==='az'?'Təkmilləşdirilmiş versiya':'Improved version'}</button><button class="btn ${S.cvMode==='compare'?'btn-primary':'btn-secondary'}" data-cv="compare">${S.lang==='az'?'Versiyaları müqayisə et':'Compare versions'}</button><hr style="border:0;border-top:1px solid var(--line);width:100%"><button class="btn btn-primary" data-improve>${I('spark')} ${S.lang==='az'?'AI ilə CV-ni təkmilləşdir':'Improve CV with AI'}</button><p class="small muted">${S.lang==='az'?'Bu, əvvəlcədən hazırlanmış demo nəticəsidir; real AI modeli istifadə edilmir.':'This is a predefined demo result; no real AI model is used.'}</p></aside>${S.cvMode==='compare'?`<div class="compare">${cvPaper(false)}${cvPaper(true)}</div>`:cvPaper(S.cvMode==='improved')}</div>`}
function cvPaper(improved){return `<article class="cv-paper"><span class="badge ${improved?'badge-orange':'badge-blue'}">${improved?'Improved Demo Version':'Original version'}</span><header class="cv-head"><h1>Aysel Məmmədova</h1><p class="muted">Junior Project Coordinator • Bakı</p></header><section class="cv-section"><h3>${S.lang==='az'?'Profil xülasəsi':'Profile summary'}</h3><p class="${improved?'changed':''}">${improved?(S.lang==='az'?'İcma layihələri və tədbir koordinasiyasında praktiki təcrübəsi olan, nəticəyönümlü gənc mütəxəssis. 5 təsdiqlənmiş fəaliyyət ərzində iştirakçı ünsiyyəti, planlama və hesabat bacarıqlarını tətbiq edib.':'Results-oriented emerging professional with hands-on experience in community projects and event coordination across 5 verified activities.'):(S.lang==='az'?'Tələbəyəm və könüllü tədbirlərdə iştirak etmişəm. Komandada işləməyi sevirəm.':'Student with volunteering experience who enjoys teamwork.')}</p></section><section class="cv-section"><h3>${S.lang==='az'?'Təcrübə':'Experience'}</h3><p class="${improved?'changed':''}"><b>EcoHub — Volunteer Coordinator</b><br>${improved?(S.lang==='az'?'40 iştirakçının qeydiyyat axınını koordinasiya etdi, tədbir planını komanda ilə icra etdi və iştirak sonrası rəyləri strukturlaşdırdı.':'Coordinated registration for 40 participants, executed the event plan with the team, and structured post-event feedback.'):(S.lang==='az'?'Tədbirdə insanlara kömək etdim və qeydiyyatda dayandım.':'Helped people at an event and worked at registration.')}</p></section><section class="cv-section"><h3>${S.lang==='az'?'Bacarıqlar':'Skills'}</h3><div class="skills">${(improved?['Project coordination','Participant communication','Excel reporting','Event planning']:['Teamwork','Microsoft Office']).map(x=>`<span class="${improved?'changed':''}">${x}</span>`).join('')}</div></section></article>`}
function candidatePage(){let data=S.page==='saved'?candidates.filter(c=>S.saved.has(c.id)):candidates;const q=(S.filters.q||'').toLowerCase();data=data.filter(c=>(!q||c.name.toLowerCase().includes(q))&&(!S.filters.city||c.city===S.filters.city));return `<div class="page-head"><div><h1>${t(S.page==='saved'?'saved':'candidates')}</h1><p>${S.lang==='az'?'Fəaliyyət və bacarıqlara əsaslanan demo profillər.':'Demo profiles based on activities and skills.'}</p></div><span class="demo-label">Demo data</span></div><div class="filters"><input class="input" data-filter="q" value="${S.filters.q||''}" placeholder="${t('search')}..."><select class="select" data-filter="city"><option value="">${t('city')}: ${t('all')}</option>${['Bakı','Gəncə','Sumqayıt'].map(x=>`<option ${S.filters.city===x?'selected':''}>${x}</option>`).join('')}</select><select class="select"><option>${S.lang==='az'?'Uyğunluq göstəricisi':'Match indicator'}</option><option>75%+</option></select><select class="select"><option>${S.lang==='az'?'Təsdiqlənmiş fəaliyyət':'Verified activity'}</option><option>3+</option></select><button class="btn btn-secondary" data-reset>${t('reset')}</button></div>${chips()}<div class="candidate-grid">${data.map(c=>candidateCard(c)).join('')}</div>${!data.length?empty():''}`}
function candidateCard(c,mini=false){return `<article class="card op-card"><div class="candidate-head"><div class="company"><span class="avatar">${c.initial}</span><div><h3>${c.name}</h3><div class="small muted">${c.city} • Demo profile</div></div></div><div class="score" style="--score:${c.score}"><b>${c.score}%</b></div></div><div class="skills">${c.skills.map(x=>`<span>${x}</span>`).join('')}</div><p>${c.acts} ${S.lang==='az'?'təsdiqlənmiş fəaliyyət':'verified activities'} • ${c.edu}</p>${mini?'':`<div class="card-actions"><button class="btn btn-secondary btn-sm" data-candidate="${c.id}">${t('view')}</button><button class="btn ${S.saved.has(c.id)?'btn-secondary':'btn-primary'} btn-sm" data-save-candidate="${c.id}">${S.saved.has(c.id)?'✓ '+(S.lang==='az'?'Saxlanıb':'Saved'):t('save')}</button></div>`}</article>`}
function matching(){if(S.matchLoading)return `<div class="loading"><div class="spinner"></div><h2>${S.lang==='az'?'Demo uyğunluqlar hazırlanır...':'Preparing demo matches...'}</h2><p class="muted">${S.lang==='az'?'Bacarıq, fəaliyyət və təcrübə sahəsi müqayisə edilir.':'Comparing skills, activities and experience areas.'}</p></div>`;return `<div class="page-head"><div><span class="demo-label">${I('spark')} AI Demo • Concept result</span><h1>${t('matching')}</h1><p>${S.lang==='az'?'Nəticələr nümunədir və real işə qəbul qərarı deyil.':'Results are illustrative and are not real hiring decisions.'}</p></div></div><section class="card ai-banner"><div style="flex:1"><label class="small muted">${S.lang==='az'?'Vakansiyanı seç':'Select vacancy'}</label><select class="select" style="width:100%;margin-top:7px"><option>Junior Project Coordinator</option><option>Content Assistant</option></select></div><button class="btn btn-primary" data-match>${I('spark')} ${S.lang==='az'?'Demo uyğunlaşdırmanı göstər':'Show demo matching'}</button></section>${S.matched?`<div class="page-head" style="margin-top:26px"><div><h1 style="font-size:22px">${S.lang==='az'?'Sıralanmış demo namizədlər':'Ranked demo candidates'}</h1><p>Example compatibility • predefined concept data</p></div></div><div class="candidate-grid">${candidates.map(c=>`<article class="card op-card">${candidateCard(c,true)}<div class="ai-reasons">${['Skill match','Activity match','Experience area','Consistency'].map((x,i)=>`<div class="reason"><b>${[94,88,85,91][i]}%</b><br><span class="muted">${x}</span></div>`).join('')}</div><div class="card-actions"><button class="btn btn-secondary btn-sm" data-candidate="${c.id}">${t('view')}</button><button class="btn btn-primary btn-sm" data-save-candidate="${c.id}">${t('save')}</button></div></article>`).join('')}</div>`:`<div class="empty" style="margin-top:18px"><span class="role-icon">${I('spark')}</span><h3>${S.lang==='az'?'Uyğunlaşdırma təqdimatını başlat':'Start the matching preview'}</h3><p class="muted">${S.lang==='az'?'Vakansiya seç və nümunə nəticələri gör.':'Select a vacancy to see sample results.'}</p></div>`}`}
function eventsPage(){return `<div class="page-head"><div><h1>${t('events')}</h1><p>${S.lang==='az'?'Aktiv, tamamlanmış və qaralama tədbirləri idarə et.':'Manage active, completed and draft events.'}</p></div><button class="btn btn-primary" data-page="create-event">${I('plus')} ${t('createEvent')}</button></div><div class="tabs"><button class="tab active">${S.lang==='az'?'Aktiv':'Active'}</button><button class="tab">${S.lang==='az'?'Tamamlanmış':'Completed'}</button><button class="tab">${S.lang==='az'?'Qaralamalar':'Drafts'}</button></div><div class="opportunity-grid">${vols.map((v,i)=>`<article class="card op-card"><div class="candidate-head"><span class="badge ${i===2?'badge-orange':'badge-green'}">${i===2?'Draft':'Active'}</span><b class="small muted">${[38,24,16][i]} participant</b></div><h3 style="margin-top:18px">${v.title}</h3><div class="meta"><span>${I('calendar')} ${v.date}</span><span>${I('map')} ${v.city}</span></div><p>${v.role}</p><div class="card-actions"><button class="btn btn-secondary btn-sm" data-toast="Event preview opened">${t('view')}</button><button class="btn btn-secondary btn-sm" data-page="create-event">${S.lang==='az'?'Redaktə et':'Edit'}</button><button class="btn btn-primary btn-sm" data-page="attendance">${t('attendance')}</button></div></article>`).join('')}</div>`}
function createPage(){const ev=S.page==='create-event';return `<div class="page-head"><div><h1>${t(ev?'createEvent':'createVacancy')}</h1><p>${S.lang==='az'?'Məlumatları daxil etdikcə önizləmə yenilənir.':'The preview updates as you enter information.'}</p></div><span class="demo-label">Live preview</span></div><div class="event-form"><form class="card form-grid" id="create-form">${f(ev?(S.lang==='az'?'Tədbir adı':'Event title'):(S.lang==='az'?'İş adı':'Job title'),'text','title','full')}${f(ev?(S.lang==='az'?'Məkan':'Location'):(S.lang==='az'?'Departament':'Department'),'text','location')}${f(t('city'),'text','city')}${f(ev?(S.lang==='az'?'Tarix':'Date'):(S.lang==='az'?'Son müraciət tarixi':'Application deadline'),'date','date')}${f(ev?(S.lang==='az'?'İştirakçı limiti':'Participant limit'):(S.lang==='az'?'İş formatı':'Work format'),'text','limit')}<div class="field full"><label>${S.lang==='az'?'Təsvir':'Description'}</label><textarea name="desc" required></textarea></div>${f(S.lang==='az'?'Tələb olunan bacarıqlar':'Required skills','text','skills','full')}<div class="field full"><div class="card-actions"><button class="btn btn-secondary" type="button" data-toast="Draft saved">${t('draft')}</button><button class="btn btn-primary" type="submit">${t(ev?'publish':'save')}</button><button class="btn btn-ghost" type="button" data-cancel-create>${t('cancel')}</button></div></div></form><aside class="card preview"><span class="badge badge-blue">Live preview</span><h2 id="prev-title">${ev?'New community event':'New vacancy'}</h2><p class="muted" id="prev-desc">${S.lang==='az'?'Formu doldurduqca bu kart yenilənəcək.':'This card updates as you fill the form.'}</p><div class="meta"><span>${I('map')} <b id="prev-city">Bakı</b></span><span>${I('calendar')} <b id="prev-date">—</b></span></div><div class="skills"><span id="prev-skills">Communication</span></div></aside></div>`}
function mapPage(){return `<div class="page-head"><div><h1>${t('map')}</h1><p>${S.lang==='az'?'Xarici xəritə xidməti olmadan hazırlanmış statik konsept.':'A static concept built without an external map service.'}</p></div><span class="demo-label">Static concept preview</span></div><div class="map"><span class="city" style="left:24%;top:27%">Gəncə</span><span class="city" style="left:59%;top:48%">Bakı</span><span class="city" style="left:46%;top:68%">Şirvan</span><button class="marker" style="left:28%;top:35%" data-map-pop="0"><span>2</span></button><button class="marker" style="left:63%;top:44%" data-map-pop="1"><span>4</span></button><button class="marker" style="left:50%;top:72%" data-map-pop="2"><span>1</span></button><div class="map-pop" style="left:66%;top:23%"><span class="badge badge-green">15 noyabr</span><h3>Yaşıl Şəhər Günü</h3><p class="small muted">EcoHub • Bakı</p><button class="btn btn-primary btn-sm" data-toast="Event preview opened">${t('view')}</button></div></div>`}
function attendance(){return `<div class="page-head"><div><h1>${t('attendance')}</h1><p>Yaşıl Şəhər Günü • 15 noyabr</p></div><select class="select"><option>Yaşıl Şəhər Günü</option><option>Kitab kampaniyası</option></select></div><div class="grid grid-2"><section class="card"><h3>${S.lang==='az'?'İştirakçılar':'Participants'}</h3><div class="list">${candidates.concat([{name:'Elvin Quliyev',initial:'EQ',city:'Bakı'}]).map((c,i)=>`<div class="list-item"><span class="avatar">${c.initial}</span><div class="grow"><b>${c.name}</b><div class="small muted">${c.city}</div></div><button class="btn ${i===2?'btn-secondary':'btn-primary'} btn-sm" data-toggle-att>${i===2?(S.lang==='az'?'Yoxdur':'Absent'):(S.lang==='az'?'İştirak edir':'Present')}</button></div>`).join('')}</div></section><section class="card"><h3>${S.lang==='az'?'İştirak göstəricisi':'Attendance rate'}</h3><div class="stat-value">75%</div><div class="progress green"><span style="width:75%"></span></div><div class="qr"></div><p class="small muted" style="text-align:center">QR Concept Preview • ${S.lang==='az'?'Real skan funksiyası yoxdur':'No real scanning functionality'}</p></section></div>`}
function profile(){return `<div class="page-head"><div><h1>${t('profile')}</h1><p>${S.lang==='az'?'Demo profil məlumatlarını redaktə et.':'Edit demo profile information.'}</p></div><button class="btn btn-secondary" data-edit-profile>${I('edit')} ${S.lang==='az'?'Redaktə et':'Edit'}</button></div><form class="card form-grid" id="profile-form">${f(S.lang==='az'?'Ad və soyad':'Full name','text','name')}${f(S.lang==='az'?'Təhsil':'Education','text','edu')}${f(t('city'),'text','city')}${f(S.lang==='az'?'Dillər':'Languages','text','languages')}${f(S.lang==='az'?'Bacarıqlar':'Skills','text','skills','full')}${f(S.lang==='az'?'Maraqlar':'Interests','text','interests','full')}<div class="field full"><div class="card-actions"><button class="btn btn-primary" type="submit">${t('save')}</button><button class="btn btn-secondary" type="reset">${t('cancel')}</button></div></div></form>`}
function genericPage(){return `<div class="page-head"><div><h1>${pageTitle()}</h1><p>${S.lang==='az'?'Bu təqdimat ekranı demo məlumatları ilə işləyir.':'This presentation screen uses demo data.'}</p></div><span class="demo-label">Concept preview</span></div><section class="card"><div class="tabs"><button class="tab active">${t('all')}</button><button class="tab">Pending</button><button class="tab">Accepted</button><button class="tab">Completed</button></div><div class="list">${jobs.slice(0,3).map((j,i)=>`<div class="list-item"><span class="company-logo">${j.company.slice(0,2)}</span><div class="grow"><b>${j.title}</b><div class="small muted">${j.company} • 0${i+3}.11.2026</div></div><span class="badge ${i===1?'badge-green':'badge-orange'}">${i===1?'Accepted':'Pending'}</span><button class="btn btn-secondary btn-sm" data-toast="Details opened">${t('view')}</button></div>`).join('')}</div></section>`}
function modalContent(){if(!S.modal)return'';if(S.modal.type==='op'){const data=S.modal.kind==='job'?jobs:vols,o=data.find(x=>x.id===S.modal.id);return `<div class="modal-wrap" data-overlay><div class="modal"><div class="modal-head"><div><span class="badge badge-blue">Demo opportunity</span><h2>${o.title}</h2></div><button class="close" data-close>${I('x')}</button></div><div class="modal-body"><p class="muted">${o.company} • ${o.city}</p><h3>${S.lang==='az'?'İmkan haqqında':'About the opportunity'}</h3><p>${o.desc||`${o.role} rolunda tədbir komandasına dəstək olacaqsınız.`}</p><h3>${S.lang==='az'?'Axtarılan bacarıqlar':'Required skills'}</h3><div class="skills">${o.skills.map(x=>`<span>${x}</span>`).join('')}</div></div><div class="modal-foot"><button class="btn btn-secondary" data-close>${S.lang==='az'?'Bağla':'Close'}</button><button class="btn btn-primary" data-apply="${o.id}">${S.applied.has(o.id)?t('applied'):t('apply')}</button></div></div></div>`}return''}
function drawerContent(){if(!S.drawer)return'';const c=candidates.find(x=>x.id===S.drawer);return `<div class="drawer-wrap" data-overlay><aside class="drawer"><div class="modal-head"><div><span class="badge badge-blue">Demo profile</span><h2>${c.name}</h2></div><button class="close" data-close>${I('x')}</button></div><div class="modal-body"><div class="candidate-head"><span class="avatar" style="width:64px;height:64px;font-size:18px">${c.initial}</span><div class="score" style="--score:${c.score}"><b>${c.score}%</b></div></div><h3>${S.lang==='az'?'Namizəd icmalı':'Candidate overview'}</h3><p class="muted">${c.edu} • ${c.city}</p><h3>${S.lang==='az'?'Bacarıqlar':'Skills'}</h3><div class="skills">${c.skills.map(x=>`<span>${x}</span>`).join('')}</div><h3>${S.lang==='az'?'Təsdiqlənmiş fəaliyyətlər':'Verified activities'}</h3><div class="list">${['Yaşıl Şəhər Günü','Karyera mentorluğu','İcma araşdırması'].map(x=>`<div class="list-item"><span class="stat-icon">${I('check')}</span><div class="grow"><b>${x}</b><div class="small muted">Verified demo activity</div></div></div>`).join('')}</div><h3>CV preview</h3><div class="card"><b>Junior Project Coordinator</b><p class="small muted">${S.lang==='az'?'Fəaliyyət əsaslı demo CV xülasəsi.':'Activity-based demo CV summary.'}</p></div></div><div class="modal-foot"><button class="btn btn-secondary" data-close>${S.lang==='az'?'Bağla':'Close'}</button><button class="btn btn-primary" data-save-candidate="${c.id}">${t('save')}</button></div></aside></div>`}
function showOverlay(){document.body.insertAdjacentHTML('beforeend',modalContent()+drawerContent());bindOverlay()}
function bind(){document.title=`${pageTitle? (S.route==='dashboard'?pageTitle():'TalantUp'):'TalantUp'} — TalantUp`;$$('[data-lang]').forEach(b=>b.onclick=()=>{S.lang=b.dataset.lang;render()});$$('[data-go="landing"]').forEach(b=>b.onclick=()=>{S.route='landing';S.menu=false;S.filters={};render()});$$('[data-auth]').forEach(b=>b.onclick=()=>{S.role=b.dataset.auth;S.route='auth';S.authTab='register';render()});$$('[data-demo]').forEach(b=>b.onclick=()=>{S.role=b.dataset.demo;S.route='dashboard';S.page='home';S.filters={};render();toast(S.lang==='az'?'Demo profil açıldı':'Demo profile opened')});$$('[data-tab]').forEach(b=>b.onclick=()=>{S.authTab=b.dataset.tab;render()});$$('[data-page]').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;S.filters={};S.menu=false;render()});$('[data-menu]')?.addEventListener('click',()=>{S.menu=!S.menu;render()});$('[data-close-menu]')?.addEventListener('click',()=>{S.menu=false;render()});$('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const btn=$('button[type=submit]',e.currentTarget);btn.disabled=true;btn.textContent=S.lang==='az'?'Yüklənir...':'Loading...';setTimeout(()=>{S.route='dashboard';S.page='home';render();toast(S.lang==='az'?'Demo hesab hazırdır':'Demo account ready')},650)});$('#cv-file')?.addEventListener('change',e=>{const f=e.target.files[0];if(f){$('#file-name').textContent=f.name;setTimeout(()=>$('#upload-bar').style.width='100%',50)}});$$('[data-filter]').forEach(el=>el.oninput=()=>{S.filters[el.dataset.filter]=el.value;render()});$$('[data-reset]').forEach(b=>b.onclick=()=>{S.filters={};render()});$$('[data-remove-filter]').forEach(b=>b.onclick=()=>{delete S.filters[b.dataset.removeFilter];render()});$$('[data-apply]').forEach(b=>b.onclick=e=>{e.stopPropagation();S.applied.add(b.dataset.apply);closeOverlay();render();toast(S.lang==='az'?'Müraciət demo siyahısına əlavə edildi':'Added to demo applications')});$$('[data-details]').forEach(b=>b.onclick=e=>{e.stopPropagation();S.modal={type:'op',id:b.dataset.details,kind:b.dataset.type};showOverlay()});$$('[data-open-op]').forEach(c=>c.onclick=e=>{if(e.target.closest('button'))return;S.modal={type:'op',id:c.dataset.openOp,kind:c.dataset.type};showOverlay()});$$('[data-cv]').forEach(b=>b.onclick=()=>{S.cvMode=b.dataset.cv;render()});$('[data-improve]')?.addEventListener('click',()=>{S.cvLoading=true;render();setTimeout(()=>{S.cvLoading=false;S.cvMode='improved';render();toast(S.lang==='az'?'AI Demo nəticəsi hazırdır':'AI Demo result is ready')},1200)});$('[data-download]')?.addEventListener('click',()=>toast(S.lang==='az'?'Demo: real PDF yaradılmır':'Demo: no real PDF is generated'));$$('[data-candidate]').forEach(b=>b.onclick=()=>{S.drawer=b.dataset.candidate;showOverlay()});$$('[data-save-candidate]').forEach(b=>b.onclick=()=>{S.saved.add(b.dataset.saveCandidate);closeOverlay();render();toast(S.lang==='az'?'Namizəd saxlanıldı':'Candidate saved')});$('[data-match]')?.addEventListener('click',()=>{S.matchLoading=true;render();setTimeout(()=>{S.matchLoading=false;S.matched=true;render();toast(S.lang==='az'?'Demo uyğunluqlar hazırdır':'Demo matches are ready')},1200)});$$('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));$('#create-form')?.addEventListener('input',e=>{const fd=new FormData(e.currentTarget);$('#prev-title').textContent=fd.get('title')||($('#prev-title').textContent);$('#prev-desc').textContent=fd.get('desc')||($('#prev-desc').textContent);$('#prev-city').textContent=fd.get('city')||'Bakı';$('#prev-date').textContent=fd.get('date')||'—';$('#prev-skills').textContent=fd.get('skills')||'Communication'});$('#create-form')?.addEventListener('submit',e=>{e.preventDefault();toast(S.lang==='az'?'Demo məlumatı saxlanıldı':'Demo data saved')});$('[data-cancel-create]')?.addEventListener('click',()=>{if(confirm(S.lang==='az'?'Saxlanmamış dəyişiklikləri silmək istəyirsiniz?':'Discard unsaved changes?')){S.page='home';render()}});$('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();toast(S.lang==='az'?'Profil dəyişiklikləri saxlanıldı':'Profile changes saved')});$$('[data-toggle-att]').forEach(b=>b.onclick=()=>{b.classList.toggle('btn-primary');b.classList.toggle('btn-secondary');b.textContent=b.classList.contains('btn-primary')?(S.lang==='az'?'İştirak edir':'Present'):(S.lang==='az'?'Yoxdur':'Absent')});}
function bindOverlay(){$$('[data-close]').forEach(b=>b.onclick=closeOverlay);$$('[data-overlay]').forEach(x=>x.onclick=e=>{if(e.target===x)closeOverlay()});$$('[data-save-candidate]').forEach(b=>b.onclick=()=>{S.saved.add(b.dataset.saveCandidate);closeOverlay();render();toast(S.lang==='az'?'Namizəd saxlanıldı':'Candidate saved')});$$('[data-apply]').forEach(b=>b.onclick=()=>{S.applied.add(b.dataset.apply);closeOverlay();render();toast(S.lang==='az'?'Müraciət edildi':'Application submitted')})}
function closeOverlay(){S.modal=null;S.drawer=null;$$('.modal-wrap,.drawer-wrap').forEach(x=>x.remove())}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlay()});
function toast(msg){$('#toast-root').innerHTML=`<div class="toast">${msg}</div>`;setTimeout(()=>{$('#toast-root').innerHTML=''},2600)}
window.addEventListener('beforeunload',e=>{if(S.route==='auth'&&$$('#auth-form input').some(x=>x.value)){e.preventDefault();e.returnValue=''}});
render();
